    if (actual <= rule.max) {
      hasPass = true;
      addPass(phase, `${rule.calc} ${actual}% is at/below max ${rule.max}%.`, {
        actual: `${actual}%`,
        expected: `<= ${rule.max}%`,
      });
    } else {
      explicitFails.push({
        calc: rule.calc,
        actual,
        max: rule.max,
