        label: item.label ?? item["⚓🎯 Label"] ?? "",
        ami: item.ami ?? item["👤AMI%"] ?? "",
        submitted: item.submitted ?? item["📅Submission Date"] ?? "",
        submissionAge: item.submissionAge ?? item["🕰️Submission Age"] ?? "",

        eligiblePrograms,
        ineligiblePrograms,

        triageScore:
            item.triageScore ??
            item["❗Triage Score"] ??
            "",

        triageMessage:
            item.triageMessage ??
            item["❗Triage Message"] ??
            "",

        triageDemo:
            item.triageDemo ??
            item["❗Triage Demo"] ??
            "",

        triageCategories,

        triageWait:
            item.triageWait ??
            item["❗Triage 🕰️Wait time"] ??
            "",

        claims: parseClaims(claimsRaw),

        propertyCardRaw,
